const r=t=>"PKR "+new Intl.NumberFormat("en-PK").format(t),i=(t,e)=>new Date(t).toLocaleDateString("en-GB",{day:"2-digit",month:"short",year:"numeric"}),s=t=>new Date(t).toLocaleTimeString("en-GB",{hour:"2-digit",minute:"2-digit"});function c(t){const e=new Date(t).getTime()-Date.now();if(e<=0)return{d:0,h:0,m:0,past:!0};const o=Math.floor(e/864e5),n=Math.floor(e%864e5/36e5),a=Math.floor(e%36e5/6e4);return{d:o,h:n,m:a,past:!1}}const f=(...t)=>t.filter(Boolean).join(" ");export{r as a,c as b,f as c,s as d,i as f};
